"""
    Escape special characters from string before passing to makefile.
    Maybe more characters will need to be added.
    """
def escape_char(string: Any) -> object {
    string = string.replace("'", "\\'");
    string = string.replace('"', '\\"');
    string = string.replace("\n", "\\n");
    return string;
}

